/* ================= INBOX — Chat · Email · Calls ================= */
S.ib={kind:'chat',dir:'all',plats:['all'],q:'',id:'v1',mt:false,draft:'',ch:null,panel:true,tr:{},mail:{box:'inbox',id:'e1',q:'',mt:false},call:{num:'',active:null,id:null,dir:'all',sec:0,mute:false,hold:false,rec:true,agent:'s3',camp:'k1'}};
TITLES.inbox=()=>'<b>Inbox</b> · '+({chat:'Chat',email:'Email',calls:'Calls'})[S.ib.kind];
const CHATP=['wa','sms','ig','msg','tt','fb','chat'];
const tick=st=>st==='sent'?`<span class="tick" data-tip="Sent">${ic('check',13)}</span>`:st==='delivered'?`<span class="tick" data-tip="Delivered">${ic('check2',15)}</span>`:`<span class="tick read" data-tip="Read">${ic('check2',15)}</span>`;
A.openConvo=el=>{closeM();hidePop();const v=D.convos.find(x=>x.id===el.dataset.id);if(!v)return;S.ib.kind='chat';S.ib.id=v.id;S.ib.mt=true;S.ib.draft='';S.ib.ch=null;v.unread=false;go('inbox')};
function ibKindBar(){return `<div class="ib-kind">${[['chat','Chat','sms'],['email','Email','mail'],['calls','Calls','phone']].map(([k,l,i])=>`<button class="${S.ib.kind===k?'on':''}" data-act="ibKind" data-v="${k}">${ic(i,14)}${l}</button>`).join('')}</div>`}
A.ibKind=el=>{S.ib.kind=el.dataset.v;rr();renderTop()};
VIEWS.inbox=()=>S.ib.kind==='email'?vEmail():S.ib.kind==='calls'?vCalls():vChat();
AFTER.inbox=()=>{const b=$('.th-b');if(b)b.scrollTop=b.scrollHeight};

/* ---------- chat ---------- */
function ibMatch(v){const b=S.ib;if(b.dir!=='all'&&v.dir!==b.dir)return false;if(!b.plats.includes('all')&&!b.plats.includes(v.plat))return false;if(b.q){const p=byId(v.cid),s=b.q.toLowerCase();if(!(cname(p)+' '+p.phone+' '+(camp(v.camp)||{name:''}).name+' '+v.items.map(i=>i.text||'').join(' ')).toLowerCase().includes(s))return false}return true}
function ibListHTML(){const L=D.convos.filter(ibMatch);return L.map(v=>{const p=byId(v.cid),last=v.items.filter(i=>i.t==='m').slice(-1)[0]||{text:'',d:'i'},cp=camp(v.camp);
 return `<button class="ib-it ${S.ib.id===v.id?'on':''}" data-act="openConvo" data-id="${v.id}"><span class="avw">${av(cname(p))}${platIc(v.plat)}</span><span class="m"><span class="l1"><span class="nmx trunc">${esc(cname(p))}</span>${v.query?`<span data-tip="Query — information only">${ic('query',12)}</span>`:''}<span class="tm">${v.time}</span></span><span class="pv trunc">${last.d==='o'?(last.st==='read'?'✓✓ ':'✓ '):''}${esc(last.text)}</span><span class="l3">${dirIc(v.dir)}${v.human?`<span class="hu-tag">${ic('user',10)}You</span>`:`<span class="ai-tag">${ic('spark',10)}${agName(v.agent)}</span>`}${v.needs?bdg('Needs a person','bad'):''}${cp?`<span class="trunc" style="max-width:110px">${esc(cp.name.split(' — ')[1]||cp.name)}</span>`:''}${cp?`<span class="faint">· ${ic('folder',10)}</span><span class="trunc" style="max-width:80px">${esc(fName(p.folder).split(' ')[0])}</span>`:''}</span></span>${v.unread?'<span class="ud"></span>':''}</button>`}).join('')||`<div class="empty">No conversations match.</div>`}
function vChat(){const b=S.ib;const v=D.convos.find(x=>x.id===b.id)||D.convos[0];b.id=v.id;const p=byId(v.cid),cp=camp(v.camp);const ch=b.ch||v.plat;
 const items=v.items.map((it,n)=>{
  if(it.t==='day')return `<div class="daysep">${esc(it.text)}</div>`;
  if(it.t==='ev'){const k=it.k==='stage'?'stage':it.k==='hand'?'hand':it.k==='book'?'book':'';return `<div class="sysev ${k}" ${it.k==='stage'?`role="button" tabindex="0" data-act="evStage" data-tip="Open Stages"`:''}>${ic(it.k==='stage'?'kanban':it.k==='hand'?'hand':it.k==='book'?'calendar':it.query?'query':'info',13)}<span>${esc(it.text)}</span><span class="faint">· ${it.time}</span></div>`}
  if(it.t==='call')return `<div class="msg ${it.d==='o'?'o':''}"><div class="callc"><div class="row between"><span class="row small">${platIc('call')}<b>${it.d==='i'?'Incoming call':'Outgoing call'}</b> · ${it.dur}</span><span class="ai-tag">${ic('spark',10)}${agName(it.who)}</span></div><div class="wave"><button class="pl" data-act="toast" data-m="Playing call recording (prototype)" aria-label="Play recording">${ic('play',12)}</button>${waveSvg()}</div><div class="small"><b>AI summary:</b> ${esc(it.summary)}</div>${b.tr[v.id+n]?`<div class="tscript">${it.tr.map(l=>`<div><b>${esc(l[0])}:</b> ${esc(l[1])}</div>`).join('')}</div>`:''}<button class="btn link small" style="align-self:flex-start" data-act="ibTr" data-k="${v.id+n}">${b.tr[v.id+n]?'Hide':'Open'} transcript</button></div><span class="meta">${it.time}</span></div>`;
  if(it.t==='inchat'&&it.k==='book')return `<div class="inchat book">${ic('bell',16)}<span class="grow"><b>Appointment request.</b> ${esc(it.text)} Handle it yourself or let the receptionist book it?</span>${btn('Handle manually','ibBookMan',{k:'sm',a:`data-n="${n}"`})}${btn('Assign to receptionist (Rhea)','ibBookRec',{k:'sm primary',a:`data-n="${n}"`})}</div>`;
  if(it.t==='inchat'&&it.k==='stage')return `<div class="inchat">${ic('spark',16)}<span class="grow"><b>This lead qualifies for “${esc(it.stage)}”.</b> ${esc(it.text)} Move it?</span>${btn('Keep in Pending','ibStNo',{k:'sm',a:`data-n="${n}"`})}${btn('Yes, move to '+esc(it.stage),'ibStYes',{k:'sm primary',a:`data-n="${n}"`})}</div>`;
  if(it.t==='quote')return `<div class="msg o"><div class="quotec"><div class="row between"><b class="row">${ic('receipt',14)}Quote ${it.no}</b>${bdg(it.status,'blue')}</div>${it.lines.map(l=>`<div class="row between small"><span>${esc(l[0])}</span><span class="num">${money(l[1],2)}</span></div>`).join('')}<div class="row between" style="border-top:1px solid var(--line-2);padding-top:6px"><b>Total</b><b class="num">${money(it.total,2)}</b></div></div><span class="meta">${it.time}</span></div>`;
  const o=it.d==='o';return `<div class="msg ${o?'o':''} ${it.who==='you'?'hu':''}"><div class="bub">${esc(it.text)}<div class="ft">${it.time}${o?tick(it.st):''}</div></div>${o?`<span class="meta">${it.who==='you'?`<span class="hu-tag">${ic('user',10)}You</span>`:`<button class="ai-tag" data-act="openAgent" data-id="${it.who}">${ic('spark',10)}${agName(it.who)}</button>`} via ${PL[v.plat].l}</span>`:''}</div>`}).join('');
 return `<div class="ibx ${b.panel?'':'nopanel'} ${b.mt?'mt':''}"><div class="ib-l"><div class="ib-head">${ibKindBar()}<div class="search">${ic('search')}<input class="in" placeholder="Search anything" value="${esc(b.q)}" data-inp="ibQ" aria-label="Search conversations"></div>
 <div class="row between">${seg([['all','All'],['in','Inbound','in'],['out','Outbound','out']],b.dir,'ibDir')}${btn('New','ibNew',{k:'sm primary',i:'plus',t:'Start a chat or send a text'})}</div>
 <div class="platf"><label><input type="checkbox" data-chg="ibPl" value="all" ${b.plats.includes('all')?'checked':''}>All</label>${CHATP.map(k=>`<label data-tip="${PL[k].l}"><input type="checkbox" data-chg="ibPl" value="${k}" ${b.plats.includes(k)&&!b.plats.includes('all')?'checked':''}>${platIc(k)}</label>`).join('')}</div></div>
 <div class="ib-list" id="iblist">${ibListHTML()}</div></div>
 <div class="th"><div class="th-h"><button class="btn icon ghost sm mback" data-act="ibBack" aria-label="Back">${ic('arrowl',16)}</button><span class="avw">${av(cname(p),'')}${platIc(v.plat)}</span><div class="grow" style="min-width:0"><div class="row nw"><button class="lnk" style="font-weight:600" data-act="openContact" data-id="${p.id}">${esc(cname(p))}</button><span class="small muted num">${esc(p.phone)}</span></div><div class="row small muted nw" style="gap:6px">${dirIc(v.dir)}${cp?`<button class="btn link small" data-act="nav" data-v="campaign" data-p='{"id":"${cp.id}"}'>${esc(cp.name)}</button>`:'Inbound'}<span class="faint">·</span>${ic('folder',11)}<span class="trunc">${esc(fName(p.folder))}</span></div></div>
 ${v.human?btn('Hand back to '+agName(v.agent),'ibHandBack',{k:'sm',i:'spark'}):btn('Take over','ibTake',{k:'sm',i:'hand'})}${btn('Assign','ibAssign',{k:'sm',i:'arrowr',a:'data-pop'})}${aiBtn('Analyze','ibAnalyze','','sm')}${iconBtn('panel','ibPanel','Show or hide contact details')}</div>
 <div class="th-b" id="thb">${items}</div>
 <div class="comp">${v.human?`<div class="banner" style="padding:6px 10px;font-size:12.5px;background:var(--primary-soft);border:0">${ic('pause',13)}${agName(v.agent)} is paused for this person while you handle it.</div>`:v.needs?`<div class="banner bad" style="padding:6px 10px;font-size:12.5px">${ic('hand',13)}${agName(v.agent)} is waiting for a person: ${esc(v.reason)}</div>`:''}
 <div class="row">${sel(CHATP.concat(['email']).map(k=>[k,'Send by '+PL[k].l]),ch,'data-chg="ibCh" aria-label="Send by"','sm auto')}${btn('Templates','ibTpl',{k:'sm ghost',i:'file',a:'data-pop'})}${aiBtn('Suggest a reply','ibSuggest','','sm')}${aiBtn('Handle with AI','ibHandBack','','sm')}<span class="grow"></span>${btn('Book','bookFor',{k:'sm',i:'calendar',a:`data-cid="${p.id}"`})}${btn('Quote','quote',{k:'sm',i:'receipt',a:`data-cid="${p.id}"`})}</div>
 <div class="aibox" style="border-radius:10px"><textarea id="ibIn" rows="1" placeholder="Write a message — sending it pauses the AI for this person" data-inp="ibDraft" data-enter="ibSend" data-auto aria-label="Message">${esc(b.draft)}</textarea>${attBtn()}${micBtn('#ibIn','Hi, thanks for your message — I can book that for you right now')}<button class="btn primary icon sm" data-act="ibSend" aria-label="Send">${ic('send',14)}</button></div></div></div>
 ${b.panel?ibPanel(v,p,cp):''}</div>`}
function ibPanel(v,p,cp){const H=histOf(p).slice(0,9);const grp=['Today','Yesterday','This week','Earlier'];
 return `<aside class="ib-r"><div class="row nw" style="gap:10px">${av(cname(p),'lg')}<div style="min-width:0"><button class="lnk" style="font-weight:600;font-size:15px" data-act="openContact" data-id="${p.id}">${esc(cname(p))}</button><div class="small muted">${esc(p.city)} · ${dirTag(p.dir)}</div></div></div>
 ${cp?`<div class="stack-s"><div class="lbl">Stage · ${esc(cp.name)}</div>${sel(stagesOf(cp).map(s=>s.n),p.stage,`data-chg="ibStage" data-id="${p.id}" aria-label="Stage"`)}</div>`:''}
 <dl class="kv"><dt>Phone</dt><dd><button class="lnk num" data-act="phoneMenu" data-id="${p.id}" data-pop>${esc(p.phone)}</button></dd><dt>Email</dt><dd>${p.email?`<button class="lnk" data-act="composeTo" data-cid="${p.id}">${esc(p.email)}</button>`:bdg('Missing','warn')}</dd><dt>Campaign</dt><dd>${cp?`<button class="lnk" data-act="nav" data-v="campaign" data-p='{"id":"${cp.id}"}'>${esc(cp.name)}</button>`:'—'}</dd><dt>Lead folder</dt><dd><button class="lnk" data-act="openFolder" data-id="${p.folder}">${esc(fName(p.folder))}</button></dd><dt>Source</dt><dd>${esc(p.source)}</dd><dt>Agent</dt><dd><button class="ai-tag" data-act="openAgent" data-id="${v.agent}">${ic('spark',10)}${agName(v.agent)}</button></dd><dt>Bought</dt><dd>${p.purchase?esc(p.purchase.product)+' · '+money(p.purchase.amount):'—'}</dd><dt>Permission</dt><dd>${['sms','call','email','wa'].filter(k=>p.consent[k]).map(k=>({sms:'Texts',call:'Calls',email:'Email',wa:'WhatsApp'})[k]).join(', ')||'None'}</dd></dl>
 <div class="grid g2" style="gap:6px">${btn('Text','newChatTo',{k:'sm',i:'sms',a:`data-cid="${p.id}"`})}${btn('Call','callNum',{k:'sm',i:'phone',a:`data-num="${esc(p.phone)}" data-cid="${p.id}"`})}${btn('Email','composeTo',{k:'sm',i:'mail',a:`data-cid="${p.id}"`})}${btn('Book','bookFor',{k:'sm',i:'calendar',a:`data-cid="${p.id}"`})}${btn('Quotation','quote',{k:'sm',i:'receipt',a:`data-cid="${p.id}"`})}${btn('Record sale','bulk',{k:'sm',i:'dollar',a:`data-k="sale" data-one="${p.id}"`})}</div>
 <div><div class="row between"><h3>History</h3><button class="btn link small" data-act="openContact" data-id="${p.id}">Full journey</button></div>${grp.map(g=>{const it=H.filter(h=>h.g===g);return it.length?`<div class="hist-g">${g}</div>${it.map(h=>`<div class="hi"><span class="hic ${h.k}" data-tip="${h.tip}">${ic(h.i,13)}</span><div class="small">${h.t}</div><span class="xs faint">${h.time}</span></div>`).join('')}`:''}).join('')}</div></aside>`}
I.ibQ=el=>{S.ib.q=el.value;$('#iblist').innerHTML=ibListHTML()};
A.ibDir=el=>{S.ib.dir=el.dataset.v;rr()};
C.ibPl=el=>{let a=S.ib.plats;if(el.value==='all'){S.ib.plats=['all']}else{a=a.filter(x=>x!=='all');const i=a.indexOf(el.value);el.checked?i<0&&a.push(el.value):a.splice(i,1);S.ib.plats=a.length?a:['all']}rr()};
A.ibBack=()=>{S.ib.mt=false;rr()};A.ibPanel=()=>{S.ib.panel=!S.ib.panel;rr()};
A.ibTr=el=>{S.ib.tr[el.dataset.k]=!S.ib.tr[el.dataset.k];rr()};
A.evStage=()=>go('stages');
I.ibDraft=el=>{S.ib.draft=el.value};C.ibCh=el=>{S.ib.ch=el.value};
const curV=()=>D.convos.find(x=>x.id===S.ib.id);
A.ibTake=()=>{const v=curV();v.human=true;v.needs=false;v.items.push(ev('sys',`You took over · ${agName(v.agent)} is paused for this person`,'now'));rr();toast('You’re handling this conversation now')};
A.ibHandBack=()=>{const v=curV();const was=v.human;v.human=false;v.needs=false;v.items.push(ev('sys',`${agName(v.agent)} is handling this conversation again`,'now'));if(!was){v.items.push(m('o',v.agent,ibSuggestText(v),'now','delivered'))}rr();toast(agName(v.agent)+' is handling it',true)};
function ibSuggestText(v){const p=byId(v.cid);return v.id==='v1'?`Hi ${p.first}, yes — I can book the installer for Saturday between 9 and 11 AM. Shall I lock that in?`:v.id==='v2'?`Hi ${p.first}, it’s Ali from Keystone Realty. Happy to talk numbers — can I call you at 6 PM today?`:`Hi ${p.first||'there'}, thanks for your message! Let me check that for you right away.`}
A.ibSuggest=()=>{const v=curV();S.ib.draft=ibSuggestText(v);const i=$('#ibIn');i.value=S.ib.draft;i.focus();toast('AI wrote a reply — edit it or send',true)};
A.ibSend=()=>{const i=$('#ibIn'),t=(i.value||'').trim();if(!t){toast('Write a message first');return}const v=curV(),ch=S.ib.ch||v.plat;const was=v.human;v.human=true;v.needs=false;v.items.push(m('o','you',t,'now','sent'));v.time='now';S.ib.draft='';rr();toast(`Sent by ${PL[ch].l}${was?'':` — ${agName(v.agent)} is paused for this person`}`);
 setTimeout(()=>{const it=v.items[v.items.length-1];if(it&&it.st==='sent'){it.st='delivered';if(S.view==='inbox')rr()}},1200);setTimeout(()=>{const it=v.items.filter(x=>x.who==='you').slice(-1)[0];if(it){it.st='read';if(S.view==='inbox')rr()}},2600)};
A.ibTpl=el=>openPop(el,`<div class="card-h" style="min-height:44px"><h3>Templates</h3></div>${['Thanks — I’ll check and get back to you today.','Your appointment is confirmed for {date} at {time}.','Here’s the link to book a time: {booking_link}','Sorry for the wait! A person from our team is here now.'].map(t=>`<button class="lr" data-act="ibTplUse" data-t="${esc(t)}">${ic('file',14)}<span class="m small">${esc(t)}</span></button>`).join('')}`);
A.ibTplUse=el=>{hidePop();const i=$('#ibIn');i.value=el.dataset.t;S.ib.draft=el.dataset.t;i.focus()};
A.ibAssign=el=>openPop(el,`<div class="card-h" style="min-height:44px"><h3>Assign this conversation</h3></div><div class="eyebrow" style="padding:8px 16px 0">AI agents</div>${D.agents.filter(a=>a.status==='live').slice(0,8).map(a=>`<button class="lr" data-act="ibAssignTo" data-a="${a.id}"><span class="av sm bot">${ic(AT[a.type].i,11)}</span><span class="m">${a.name} <span class="small muted">· ${AT[a.type].l}</span></span></button>`).join('')}<div class="eyebrow" style="padding:8px 16px 0">People</div>${D.team.map(t=>`<button class="lr" data-act="ibAssignTo" data-u="${esc(t[0])}">${av(t[0],'sm')}<span class="m">${esc(t[0])} <span class="small muted">· ${t[1]}</span></span></button>`).join('')}`);
A.ibAssignTo=el=>{hidePop();const v=curV();if(el.dataset.a){v.agent=el.dataset.a;v.human=false;v.items.push(ev('sys',`${agName(el.dataset.a)} was assigned to this conversation`,'now'));toast(agName(el.dataset.a)+' now handles this chat')}else{v.human=true;v.items.push(ev('sys',`Assigned to ${el.dataset.u}`,'now'));toast('Assigned to '+el.dataset.u+' — they’ve been notified')}rr()};
A.ibAnalyze=()=>{const v=curV(),p=byId(v.cid);openM('aiNote',{title:'Analyze this chat · '+cname(p),body:`<ul><li><b>Mood:</b> ${v.needs?'frustrated — wants a person':'positive'}.</li><li><b>Stage:</b> ${esc(p.stage)} — AI is 92% sure it’s correct.</li><li><b>What they want:</b> ${v.id==='v1'?'installation before noon on Saturday':v.id==='v2'?'to negotiate the price with a person':'more information'}.</li><li><b>Agent mistakes:</b> none found.</li><li><b>Next best step:</b> ${v.id==='v1'?'book Saturday 9–11 AM with Install team A':'reply within 5 minutes'}.</li></ul>`})};
C.ibStage=el=>{moveLead(el.dataset.id,el.value,'you');if(S.view==='inbox')rr()};
A.ibBookRec=el=>{const v=curV();v.items.splice(+el.dataset.n,1);v.items.push(ev('sys','Rhea (Receptionist) joined to book the appointment','now'),m('o','r1',`Hi ${byId(v.cid).first}, I’m Rhea from Metro Mobile. I can book your installer Saturday between 9 and 11 AM. Shall I lock that in?`,'now','delivered'));const a=D.assigned.find(x=>x.convo===v.id&&x.kind==='book');if(a)a.done=true;renderTop();rr();toast('Rhea is booking it — you’ll see it in Bookings',true)};
A.ibBookMan=el=>{const v=curV(),p=byId(v.cid);openBooking({camp:'k1',who:cname(p),cid:p.id,svc:'Fiber installation',asg:(D.assigned.find(x=>x.convo===v.id&&x.kind==='book')||{}).id})};
A.ibStYes=el=>{const v=curV(),it=v.items[+el.dataset.n];v.items.splice(+el.dataset.n,1);moveLead(v.cid,it.stage,'you');if(S.view==='inbox')rr()};
A.ibStNo=el=>{const v=curV();v.items.splice(+el.dataset.n,1);const p=byId(v.cid);p.stage='Pending';v.items.push(ev('stage','Kept in Pending by you','now',{stage:'Pending'}));rr();toast('Kept in Pending — you’ll see it in Stages')};
/* new outreach */
A.ibNew=()=>openM('newChat',{cid:'',num:'',plat:'sms',text:'',mode:'me',agent:'s1',camp:'k1'});
A.newChatTo=el=>{hidePop();const c=byId(el.dataset.cid);openM('newChat',{cid:c.id,num:c.phone,plat:c.consent.wa?'wa':'sms',text:'',mode:'me',agent:c.agent||'s1',camp:c.camp||'k1'})};
M.newChat=m=>MS('New message',`<div class="fgrid two">${fld('To',`<input class="in" list="ncL" value="${esc(m.cid?cname(byId(m.cid))+' · '+m.num:m.num)}" placeholder="Name or phone number" data-inp="ncTo" data-autofocus><datalist id="ncL">${D.contacts.filter(c=>c.name).map(c=>`<option value="${esc(c.name+' · '+c.phone)}">`).join('')}</datalist>`)}${fld('Send by',sel(CHATP.map(k=>[k,PL[k].l]),m.plat,'data-chg="ncPlat"'))}</div>
 ${seg([['me','Send it myself','user'],['ai','Assign to an AI agent','spark']],m.mode,'ncMode')}
 ${m.mode==='me'?fld('Message',`<div class="aibox" style="border-radius:10px"><textarea id="ncT" rows="3" placeholder="Write your message" data-inp="ncText">${esc(m.text)}</textarea>${attBtn()}${micBtn('#ncT','Hi, just checking in about your internet order')}</div><div class="row" style="margin-top:6px">${btn('Write with AI','aiFill',{k:'xs ai',i:'spark',a:`data-target="#ncT" data-text="Hi! It’s Bilal from Metro Mobile — just checking in. Would you like me to book your free installation this week?"`})}</div>`):`<div class="fgrid two">${fld('Agent',sel(D.agents.map(a=>[a.id,a.name+' · '+AT[a.type].l]),m.agent,'data-chg="ncAg"'))}${fld('Follow this campaign’s instructions',sel(D.campaigns.map(c=>[c.id,c.name]),m.camp,'data-chg="ncCamp"'))}</div><div class="banner ai small">${ic('spark',14)}${agName(m.agent)} will start the conversation using the campaign’s opening message, script and follow-ups, and move the lead through its stages.</div>`}`,`${btn('Cancel','close',{k:'ghost'})}${btn(m.mode==='me'?'Send':'Start with '+agName(m.agent),'ncSend',{k:'primary',i:'send'})}`);
I.ncTo=el=>{S.modal.num=el.value;S.modal.cid=''};C.ncPlat=el=>{S.modal.plat=el.value};A.ncMode=el=>{S.modal.mode=el.dataset.v;renderModal()};I.ncText=el=>{S.modal.text=el.value};C.ncAg=el=>{S.modal.agent=el.value;renderModal()};C.ncCamp=el=>{S.modal.camp=el.value};
