function vCalls(){const cl=S.ib.call;const L=D.calls.filter(x=>cl.dir==='all'||(cl.dir==='missed'?x.status==='missed':x.dir===cl.dir));const cur=D.calls.find(x=>x.id===cl.id);
 const who=x=>x.cid?cname(byId(x.cid)):x.num;
 return `<div class="ibx nopanel"><div class="ib-l"><div class="ib-head">${ibKindBar()}${seg([['all','All'],['in','Inbound','in'],['out','Outbound','out'],['missed','Missed']],cl.dir,'clDir')}${btn('New call','clNew',{k:'sm primary',i:'phone'})}</div><div class="ib-list">${L.map(x=>`<button class="ib-it ${cl.id===x.id?'on':''}" data-act="clOpen" data-id="${x.id}"><span class="avw">${av(who(x))}<span class="plat p-call">${ic(x.status==='missed'||x.status==='failed'?'phoneoff':x.dir==='in'?'phonein':'phone',10)}</span></span><span class="m"><span class="l1"><span class="nmx trunc" style="${x.status==='missed'?'color:var(--bad)':''}">${esc(who(x))}</span><span class="tm">${x.time}</span></span><span class="pv trunc">${esc(x.summary)}</span><span class="l3">${dirIc(x.dir==='in'?'in':'out')}${x.by==='you'?`<span class="hu-tag">${ic('user',10)}You</span>`:x.by?`<span class="ai-tag">${ic('spark',10)}${agName(x.by)}</span>`:''}<span>${x.status==='answered'?x.dur:x.status}</span></span></span></button>`).join('')}</div></div>
 <div class="th" style="background:var(--surface)">${cl.active?clActive():cur?`<div class="th-h"><button class="btn icon ghost sm mback" data-act="clBack" aria-label="Back">${ic('arrowl',16)}</button>${av(who(cur))}<div class="grow"><b>${esc(who(cur))}</b><div class="small muted">${cur.dir==='in'?'Incoming':'Outgoing'} · ${cur.time} · ${cur.status}${cur.camp?' · '+esc(camp(cur.camp).name):''}</div></div>${cur.cid?btn('Contact','openContact',{k:'sm',a:`data-id="${cur.cid}"`}):''}${btn('Call back','callNum',{k:'sm primary',i:'phone',a:`data-num="${esc(cur.cid?byId(cur.cid).phone:cur.num)}"`})}</div><div class="th-b" style="background:var(--surface)"><div class="callc" style="width:100%;max-width:640px"><div class="wave"><button class="pl" data-act="toast" data-m="Playing recording (prototype)" aria-label="Play">${ic('play',12)}</button>${waveSvg()}<span class="small muted">${cur.dur}</span></div><div><b>AI summary:</b> ${esc(cur.summary)}</div><div class="tscript"><div><b>${cur.by&&cur.by!=='you'?agName(cur.by):'You'}:</b> Hi, this is ${cur.by&&cur.by!=='you'?agName(cur.by):'Bilal'} from ${cur.camp?esc(camp(cur.camp).biz):'Metro Mobile'}. How can I help?</div><div><b>${esc(who(cur))}:</b> ${esc(cur.summary)}</div></div></div><div class="row">${aiBtn('Analyze this call','ibAnalyze','','sm')}${btn('Download recording','toast',{k:'sm',i:'download',a:'data-m="Recording downloads in the real app"'})}</div></div>`:clPad()}</div></div>`}
function clPad(){const cl=S.ib.call;const keys=[['1',''],['2','ABC'],['3','DEF'],['4','GHI'],['5','JKL'],['6','MNO'],['7','PQRS'],['8','TUV'],['9','WXYZ'],['*',''],['0','+'],['#','']];
 return `<div class="th-b" style="align-items:center;justify-content:center;background:var(--surface)"><div class="stack" style="align-items:center;width:min(360px,100%)"><div class="row small muted">${ic('phone',14)}Calling from ${sel(D.numbers.map(n=>[n.n,n.n+' · '+n.l]),D.numbers[0].n,'aria-label="From number"','sm auto')}</div><input class="dialnum" id="dialN" value="${esc(cl.num)}" placeholder="Enter a number" data-inp="clNum" aria-label="Number" list="clL"><datalist id="clL">${D.contacts.filter(c=>c.name).map(c=>`<option value="${esc(c.phone)}">${esc(c.name)}</option>`).join('')}</datalist>
 <div class="dialer">${keys.map(([k,s])=>`<button data-act="clKey" data-k="${k}">${k}<small>${s}</small></button>`).join('')}</div>
 <div class="row" style="justify-content:center;gap:16px"><button class="callbtn" data-act="clCall" aria-label="Call" data-tip="Call yourself">${ic('phone',22)}</button>${iconBtn('x','clDel','Delete digit')}</div>
 <div class="card pad stack-s" style="width:100%;background:var(--ai-soft);border-color:var(--ai-line)"><b class="small">${ic('spark',13)} Or let an AI agent make this call</b><div class="row nw">${sel(D.agents.filter(a=>a.act.callOut).map(a=>[a.id,a.name+' · '+AT[a.type].l]),cl.agent,'data-chg="clAg" aria-label="Agent"','sm')}${sel(D.campaigns.map(c=>[c.id,c.name]),cl.camp,'data-chg="clCamp" aria-label="Campaign"','sm')}</div>${btn('Assign the call to '+agName(cl.agent),'clAI',{k:'sm primary',i:'spark'})}<span class="xs muted">The agent follows that campaign’s script and updates the stage.</span></div></div></div>`}
function clActive(){const a=S.ib.call.active;const t=Math.floor((Date.now()-a.t0)/1000);return `<div class="incall" style="margin:auto">${av(a.name,'xl')}<h2>${esc(a.name)}</h2><div class="muted num" id="clTimer">${a.ai?agName(a.ai)+' is on the call · ':''}${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}</div>${a.ai?`<div class="card pad small" style="max-width:420px;text-align:left" id="clLive">${(a.lines||[]).map(l=>`<div><b>${esc(l[0])}:</b> ${esc(l[1])}</div>`).join('')}</div>`:''}
 <div class="ctl">${[['mute','micoff','Mute'],['hold','pause','Hold'],['pad','dial','Keypad'],['rec','stop','Record']].map(([k,i,l])=>`<button class="${S.ib.call[k]?'on':''}" data-act="clTog" data-k="${k}">${ic(i,18)}${l}</button>`).join('')}<button data-act="clXfer">${ic('transfer',18)}Transfer</button><button data-act="clToAI">${ic('spark',18)}To AI</button><button data-act="clNote">${ic('edit',18)}Notes</button><button data-act="bookFor" data-cid="${a.cid||'c1'}">${ic('calendar',18)}Book</button></div>
 <button class="callbtn end" data-act="clEnd" aria-label="End call">${ic('phoneoff',22)}</button></div>`}
A.clDir=el=>{S.ib.call.dir=el.dataset.v;rr()};A.clOpen=el=>{S.ib.call.id=el.dataset.id;S.ib.mt=true;rr()};A.clBack=()=>{S.ib.call.id=null;rr()};A.clNew=()=>{S.ib.call.id=null;S.ib.call.active=null;rr()};
I.clNum=el=>{S.ib.call.num=el.value};A.clKey=el=>{S.ib.call.num+=el.dataset.k;$('#dialN').value=S.ib.call.num};A.clDel=()=>{S.ib.call.num=S.ib.call.num.slice(0,-1);$('#dialN').value=S.ib.call.num};
C.clAg=el=>{S.ib.call.agent=el.value;rr()};C.clCamp=el=>{S.ib.call.camp=el.value};
let clTimer=null;
function clStart(num,cid,ai){const c=cid?byId(cid):D.contacts.find(x=>x.phone===num);S.ib.kind='calls';S.ib.call.active={num,cid:c?c.id:null,name:c?cname(c):num,t0:Date.now(),ai,lines:[]};S.ib.call.num=num;if(S.view!=='inbox')go('inbox');else rr();clearInterval(clTimer);clTimer=setInterval(()=>{const t=$('#clTimer');if(!S.ib.call.active||!t){clearInterval(clTimer);return}const s=Math.floor((Date.now()-S.ib.call.active.t0)/1000);t.textContent=(ai?agName(ai)+' is on the call · ':'')+String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')},1000);
 if(ai){const L=[[agName(ai),`Hi ${c?c.first:''}, it’s ${agName(ai)}, Metro Mobile’s AI assistant. Is now a good time?`],[c?c.first||'Customer':'Customer','Yes, go ahead.'],[agName(ai),'Great — Internet 1 Gig is $50/month with free installation. Do you have internet now?'],[c?c.first||'Customer':'Customer','Yes, with Bell. I pay $85.'],[agName(ai),'You’d save $35 a month. Shall I book the installation for Saturday?']];let i=0;const t=setInterval(()=>{const a=S.ib.call.active;if(!a||i>=L.length){clearInterval(t);return}a.lines.push(L[i++]);const box=$('#clLive');if(box)box.innerHTML=a.lines.map(l=>`<div><b>${esc(l[0])}:</b> ${esc(l[1])}</div>`).join('')},1300)}}
A.callNum=el=>{hidePop();closeM();clStart(el.dataset.num,el.dataset.cid,null);toast('Calling '+el.dataset.num+' (prototype — no real call is placed)')};
A.clCall=()=>{const n=($('#dialN').value||'').trim();if(!n){toast('Enter a number');return}clStart(n,null,null)};
A.clAI=()=>{const n=($('#dialN').value||'').trim();if(!n){toast('Enter a number first');return}const cl=S.ib.call;clStart(n,null,cl.agent);toast(agName(cl.agent)+' is calling — the stage updates when the call ends',true)};
A.clTog=el=>{S.ib.call[el.dataset.k]=!S.ib.call[el.dataset.k];rr()};
A.clXfer=el=>openPop(el,`<div class="card-h" style="min-height:44px"><h3>Transfer to</h3></div>${D.team.map(t=>`<button class="lr" data-act="clXferTo" data-u="${esc(t[0])}">${av(t[0],'sm')}<span class="m">${esc(t[0])}</span></button>`).join('')}${D.agents.filter(a=>a.type==='reception'||a.type==='support').map(a=>`<button class="lr" data-act="clXferTo" data-u="${esc(a.name)} (AI)"><span class="av sm bot">${ic(AT[a.type].i,11)}</span><span class="m">${a.name} · ${AT[a.type].l}</span></button>`).join('')}`);
A.clXferTo=el=>{hidePop();toast('Transferred to '+el.dataset.u)};
A.clToAI=()=>{const a=S.ib.call.active;a.ai=S.ib.call.agent;toast(agName(a.ai)+' took over the call',true);rr()};
A.clNote=()=>openM('aiNote',{title:'Call notes',body:`<textarea class="in" style="min-height:140px" placeholder="Notes are saved to the contact’s history"></textarea><p class="small muted">AI also writes a summary when the call ends.</p>`});
A.clEnd=()=>{const a=S.ib.call.active;if(!a)return;const s=Math.floor((Date.now()-a.t0)/1000);D.calls.unshift({id:uid('l'),cid:a.cid,num:a.num,dir:'out',status:'answered',by:a.ai||'you',camp:S.ib.call.camp,dur:`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`,time:'just now',summary:a.ai?'Customer interested — installation offered for Saturday.':'Call by you — AI summary ready in a minute.'});if(a.cid){const c=byId(a.cid);c.last=0;c.attempts++}S.ib.call.active=null;S.ib.call.id=D.calls[0].id;clearInterval(clTimer);rr();toast('Call ended — recording, summary and history saved')};
